-- The brands the platform can run as (T347; constitution X, FR-090-FR-097), generated by Prisma
-- from schema.prisma, plus a hand-written check that a token version is never below 1.
-- CreateTable
CREATE TABLE "Brand" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "tokens" JSONB NOT NULL,
    "content" JSONB NOT NULL,
    "hosts" TEXT[],
    "tokenVersion" INTEGER NOT NULL DEFAULT 1,
    "seedHash" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Brand_pkey" PRIMARY KEY ("id")
);


-- AddCheck (hand-written): versions count up from 1.
ALTER TABLE "Brand" ADD CONSTRAINT "Brand_tokenVersion_check" CHECK ("tokenVersion" >= 1);
